"use server";

import { apiv3Get } from "@/lib/apiv3";

/**
 * Blog okuma uçları (login'siz) — apiv3 `blog/*`. Server action: apiv3 b2c uçları
 * `X-App-Token` (server-side gizli) ister, bu yüzden client component'ler RPC ile çağırır.
 *
 * apiv3 her uçta tutarlı `{ data: … }` döner; tüketiciler legacy şekline göre yazıldığından
 * burada uyarlanır: liste `{data, meta}` aynen, kategoriler düz dizi, detay düz nesne.
 *
 * NOT: blog yazma/admin uçları (`blogPageService.ts`) ve `post/{slug}/attractions`
 * hâlâ legacy api'de; `tag` filtresi tsbnext'te kullanılmadığı için taşınmadı.
 */

type BlogPostsParams = {
  page?: number;
  limit?: number;
  search?: string;
  category?: string;
  author_id?: any;
  tag?: string; // tsbnext'te kullanılmıyor; çağrı uyumu için tutuldu (yok sayılır)
  sort?: string;
};

/** Yayınlanmış gönderiler (sayfalı) — `{ data, meta }` aynen döndürülür. */
export async function getBlogPosts({
  page = 1,
  limit = 12,
  search = "",
  category = "",
  author_id = "",
  sort = "newest",
}: BlogPostsParams) {
  const query = new URLSearchParams();
  query.set("limit", String(limit));
  query.set("page", String(page));
  if (search) query.set("search", search);
  if (category) query.set("category", category);
  if (author_id) query.set("author_id", String(author_id));
  query.set("sort", sort || "newest");

  const res = await apiv3Get(`/blog/posts?${query.toString()}`, { revalidate: 0 });
  if (!res.ok) throw new Error("Failed to fetch data");
  return res.json();
}

/** Yayınlanmış gönderisi olan kategoriler — düz dizi döndürülür. */
export async function getCategories() {
  const res = await apiv3Get("/blog/categories");
  if (!res.ok) throw new Error("Failed to fetch data");
  const json = await res.json();
  return json.data ?? [];
}

/** Tek gönderi detayı — düz nesne; bulunamazsa null. */
export async function getPostDetails(slug: string) {
  const res = await apiv3Get(`/blog/posts/${slug}`, { revalidate: 300 });
  if (!res.ok) return null;
  const json = await res.json();
  return json.data ?? null;
}

/**
 * Bir lokasyona bağlı yayınlanmış yazılar — kategori sayfasının "Travel Guides"
 * sekmesi. Eşleşme apiv3 tarafında doğrudan (yazının lokasyonu = sayfanın
 * lokasyonu); eşleşme yoksa boş dizi döner ve sekme hiç render edilmez.
 */
export async function getPostsByLocation(locationId: number, limit = 6) {
  if (!locationId) return [];

  try {
    const res = await apiv3Get(
      `/blog/posts/by-location?locationId=${locationId}&limit=${limit}`,
      { revalidate: 3600 },
    );
    if (!res.ok) return [];
    const json = await res.json();
    return json.data ?? [];
  } catch {
    // Blog bloğu yan içerik — hatası kategori sayfasını düşürmemeli.
    return [];
  }
}
