"use server";

import { cookies } from "next/headers";

/**
 * B2C login: the apiv3 `/auth/login` call is made on the SERVER because:
 *  - X-App-Token is a private server secret (APIV3_APP_TOKEN, not NEXT_PUBLIC);
 *    it must never be sent from the client.
 *  - The audience (role) gate is applied here, so a rejected user never
 *    receives a token.
 *
 * apiv3 returns `{ token (Sanctum), token_old (api_token), user }`. The client
 * writes the cookies (most legacy calls are made from the client with
 * api_token, so the token has to be returned to the client).
 */

// The main site audience is CUSTOMER only. Operator and blogger panels moved to
// business (see lib/partnerLinks); those accounts are rejected here with a
// `reason`, and the screen redirects them to the panel.
const DEFAULT_ALLOWED_ROLES = ["customer"];

type LoginUser = {
  id: number;
  email: string;
  name: string;
  avatar: string | null;
  roles: string[];
};

type LoginResult =
  | { ok: true; token: string; token_old: string; user: LoginUser }
  | { ok: false; reason?: "operator" | "blogger" | "role" | "invalid" };

/**
 * Central login: customer/blogger use the same apiv3 `/auth/login` endpoint;
 * the only difference is the allowed role set. apiv3 authenticates everyone and
 * returns a token; the audience (role) gate is applied HERE: if the role does
 * not match, no token is returned.
 */
export async function loginAction(
  email: string,
  password: string,
  allowedRoles: string[] = DEFAULT_ALLOWED_ROLES
): Promise<LoginResult> {
  try {
    const res = await fetch(`${process.env.NEXT_PUBLIC_APIV3_URL}/auth/login`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-App-Token": process.env.APIV3_APP_TOKEN ?? "",
      },
      body: JSON.stringify({ email, password }),
      cache: "no-store",
    });

    if (!res.ok) return { ok: false, reason: "invalid" };

    const data = await res.json();
    const roles: string[] = Array.isArray(data?.user?.roles) ? data.user.roles : [];
    if (roles.includes("operator")) return { ok: false, reason: "operator" };
    if (roles.includes("blogger")) return { ok: false, reason: "blogger" };

    const allowed = roles.some((r: string) => allowedRoles.includes(r));
    if (!data?.token || !allowed) return { ok: false, reason: "role" };

    return {
      ok: true,
      token: data.token,
      token_old: data.token_old,
      user: data.user,
    };
  } catch {
    return { ok: false };
  }
}

/**
 * Profile of the logged-in user: apiv3 `/auth/me` (Sanctum, `auth-token-v3`).
 * Since all tsbnext calls moved to apiv3, the legacy api `/auth/user`
 * fallback was REMOVED. Returns the plain user object, or null on failure.
 */
export async function getMe(): Promise<Record<string, unknown> | null> {
  const v3 = await (await cookies()).get("auth-token-v3")?.value;
  if (!v3) return null;

  try {
    const res = await fetch(`${process.env.NEXT_PUBLIC_APIV3_URL}/auth/me`, {
      headers: { Accept: "application/json", Authorization: `Bearer ${v3}` },
      cache: "no-store",
    });
    if (!res.ok) return null;
    const data = await res.json();
    return data?.user ?? null;
  } catch {
    return null;
  }
}

/* ------------------------------------------------------------------ */
/* Administrator login: POST {ADMIN_API_URL}/api/v1/administrator/login */
/* ------------------------------------------------------------------ */

type AdminLoginResult =
  | {
      ok: true;
      user: { id: string; name: string; email: string; role: string };
    }
  | { ok: false; reason: "invalid" | "unreachable" | "error"; message: string };

/**
 * Authenticates an administrator and stores the returned token in an
 * httpOnly cookie (`admin-token`). The token is NOT returned to the client,
 * so browser JavaScript can never read it.
 */
export async function adminLoginAction(
  username: string,
  password: string
): Promise<AdminLoginResult> {
  const base = process.env.ADMIN_API_URL ?? "http://localhost:3000";

  let res: Response;
  try {
    res = await fetch(`${base}/api/v1/administrator/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify({ username, password }),
      cache: "no-store",
    });
  } catch (err) {
    console.error("Admin login: API unreachable:", err);
    return {
      ok: false,
      reason: "unreachable",
      message: "Could not reach the authentication server.",
    };
  }

  const raw = await res.text();
  let json: any = null;
  try {
    json = raw ? JSON.parse(raw) : null;
  } catch {
    json = null;
  }

  if (!res.ok) {
    console.error("Admin login failed:", res.status, raw.slice(0, 300));
    if ([400, 401, 403, 404, 422].includes(res.status)) {
      return {
        ok: false,
        reason: "invalid",
        message: json?.message ?? "Invalid username or password.",
      };
    }
    return {
      ok: false,
      reason: "error",
      message: json?.message ?? `Login failed (HTTP ${res.status}).`,
    };
  }

  // ---- Adjust this block if your response shape is different ----
  const root = json?.data ?? json ?? {};
  const token: string | undefined =
    root?.token ?? root?.access_token ?? root?.accessToken ??
    json?.token ?? json?.access_token ?? json?.accessToken;
  const u = root?.user ?? root?.administrator ?? root?.admin ?? root?.profile ?? {};
  // ---------------------------------------------------------------

  if (!token) {
    console.error("Admin login: no token in response:", raw.slice(0, 300));
    return {
      ok: false,
      reason: "error",
      message: "Login succeeded but no token was returned.",
    };
  }

  (await cookies()).set("admin-token", token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: 60 * 60 * 8, // 8 hours
  });

  const rawRole = Array.isArray(u?.roles) ? u.roles[0] : u?.role;
  return {
    ok: true,
    user: {
      id: String(u?.id ?? ""),
      name: u?.name ?? u?.full_name ?? u?.username ?? username,
      email: u?.email ?? username,
      role: typeof rawRole === "string" ? rawRole : (rawRole?.name ?? "admin"),
    },
  };
}

/** Returns the administrator token for server-side calls (or null). */
export async function getAdminToken(): Promise<string | null> {
  return (await (await cookies()).get("admin-token")?.value) ?? null;
}

export async function adminLogoutAction(): Promise<void> {
  (await cookies()).delete("admin-token");
}